"use strict";(function(){function p(t){let e=(n,...i)=>l(o(t,n),n,...i).join("");return e.asArray=(n,...i)=>l(o(t,n),...i),e}function s(t){let e=(...n)=>l(t,...n).join("");return e.asArray=(...n)=>l(t,...n),e}function o(t,e){return t[i18n.quantity(e)]||t.other||t.one||""}function l(t,...e){let n=t.split(/(%(?:\d\$)?s)/);if(e.length){let i=n.indexOf("%s");if(i!=-1)n[i]=e[0];else for(let r=0;r<e.length;r++){let f=n.indexOf("%"+(r+1)+"$s");f!=-1&&(n[f]=e[r])}}return n}
let i=window.i18n.puzzleTheme={};i['advancedPawn']="மேம்பட்ட பணயம்";i['advancedPawnDescription']="உங்கள் பணயங்களில் ஒன்று எதிராளியின் நிலைமையில் ஆழமாக உள்ளது, ஒருவேளை பதவி உயர்வுக்கு அச்சுறுத்தலாக இருக்கலாம்.";i['advantage']="ஆதாயம்";i['advantageDescription']="ஒரு தீர்க்கமான ஆதாயத்தைப் பெறுவதற்கான உங்கள் வாய்ப்பைப் பயன்படுத்திக் கொள்ளுங்கள். (200cp ≤ கணிப்பு ≤ 600cp)";i['anastasiaMate']="அனசுதேசியாவின் முற்றுகை";i['anastasiaMateDescription']="ஒரு குதிரை மற்றும் யானை அல்லது அரசியும் இணைந்து எதிரணி அரசரைப் பலகையின் பக்கத்திற்கும் நட்பு துண்டுக்கும் இடையில் சிக்க வைக்கிறார்கள்.";i['arabianMate']="அரேபிய முற்று";i['arabianMateDescription']="ஒரு குதிரை மற்றும் ஒரு யானையும் இணைந்து எதிரணி அரசரைப் பலகையின் ஒரு மூலையில் சிக்க வைக்கின்றனர்.";i['attackingF2F7']="சிப்பாய் f2 அல்லது சிப்பாய் f7 ஐத் தாக்குதல்";i['attackingF2F7Description']="வறுத்த கல்லீரல் துவக்கம் போன்ற, f2 அல்லது f7 பணயத்தை மையமாகக் கொண்ட தாக்குதல்.";i['attraction']="ஈர்ப்பு";i['attractionDescription']="பரிமாற்றமோ அல்லது பலியோ, சூழ்ச்சி நிறைந்த சதுக்கத்திற்கு எதிராளியின் துண்டை ஊக்குவித்தல் அல்லது கட்டாயப்படுத்துதல்.";i['backRankMate']="பின் வரிசை முற்றுகை";i['backRankMateDescription']="அரசர் அதன் சொந்த துண்டுகளால் சிக்கிக் கொள்ளும்போது, ​​இருப்பிடத் தரவரிசையில் முற்றுகையிடுதல்.";i['balestraMate']="Balestra mate";i['balestraMateDescription']="A bishop delivers the checkmate, while a queen blocks the remaining escape squares";i['bishopEndgame']="நெடுங்கோணி கடையாட்டம்";i['bishopEndgameDescription']="நெடுங்கோணிகளும் பணயங்களும் மட்டுமே கொண்ட ஒரு கடையாட்டம்.";i['blindSwineMate']="Blind Swine mate";i['blindSwineMateDescription']="Two rooks team up to mate the king in an area of 2 by 2 squares.";i['bodenMate']="போடனின் முற்றுகை";i['bodenMateDescription']="நட்புத் துண்டுகளால் தடுக்கப்பட்ட ஒரு அரசருக்கு, குறுக்காகக் கடக்கும் மூலைவிட்டங்களில் தாக்குதல் நடத்தும் இரு நெடுங்கோணிகள் முற்றுகையிடுகிறார்கள்.";i['capturingDefender']="பாதுகாவலரைப் பிடிக்கவும்";i['capturingDefenderDescription']="மற்றொரு காயின் பாதுகாப்பிற்கு முக்கியமான ஒரு காயை அகற்றுதல், தற்போது பாதுகாக்கப்படாத காயை அடுத்த நகர்வில் கைப்பற்ற அனுமதிக்கிறது.";i['castling']="கோட்டை கட்டுதல்";i['castlingDescription']="அரசரைப் பாதுகாப்பிற்குள் கொண்டு வாருங்கள், மற்றும் தாக்குதலுக்கு யானையைக் களமிறக்குங்கள்.";i['clearance']="அப்புறப்படுத்து";i['clearanceDescription']="பெரும்பாலும் ஊக்கத்துடன் கூடிய ஒரு நகர்வானது சூழ்ச்சி எண்ணத்திற்காக ஒரு சதுக்கம், வரிசை அல்லது மூலைவிட்டத்தை அப்புறப்படுத்தும்.";i['collinearMove']="Collinear move";i['collinearMoveDescription']="Two opposing pieces face each other, and one slides along the line of attack without capturing the enemy piece.";i['cornerMate']="Corner mate";i['cornerMateKnightDeliversDescription']="Confine the king to the corner using a rook or queen, and use a knight to deliver the checkmate.";i['crushing']="நசுக்குதல்";i['crushingDescription']="எதிராளியின் தவறைக் கண்டுபிடித்து, ஒரு நசுக்கும் ஆதாயத்தைப் பெறுங்கள். (கணிப்பு ≥ 600cp)";i['defensiveMove']="தற்காப்பு நகர்வு";i['defensiveMoveDescription']="பொருள் அல்லது மற்றொரு ஆதாயத்தை இழப்பதைத் தவிர்க்கத் தேவையான ஒரு துல்லியமான நகர்வு அல்லது நகர்வுகளின் தொடர்வரிசை.";i['deflection']="திசை திருப்புதல்";i['deflectionDescription']="எதிராளியின் துண்டை அது செய்யும் மற்றொரு கடமையிலிருந்து திசைதிருப்பும் ஒரு நகர்வு, எடுத்துக்காட்டாக ஒரு முக்கிய சதுக்கத்தைப் பாதுகாப்பது. சில வேளைகளில் \"மிகுசுமை\" என்றும் அழைக்கப்படுகிறது.";i['discoveredAttack']="வெளிபடுத்திய தாக்குதல்";i['discoveredAttackDescription']="தொலை தூரத் துண்டின் (யானைபோல்) தாக்குதலைத் தடுத்த ஒரு துண்டு (குதிரைபோல்), அந்தத் துண்டை வழியிலிருந்து நகர்த்துதல்.";i['discoveredCheck']="Discovered check";i['discoveredCheckDescription']="Move a piece to reveal a check from a hidden attacking piece, which often leads to a decisive advantage.";i['doubleBishopMate']="இரட்டை நெடுங்கோணி முற்றுகை";i['doubleBishopMateDescription']="நட்பு துண்டுகளால் தடுக்கப்பட்ட ஒரு அரசரை, அடுத்தடுத்த மூலைவிட்டங்களில் தாக்குதல் நடத்தும் இரு நெடுங்கோணிகள், முற்றுகையிடுகிறார்கள்.";i['doubleCheck']="இரட்டை அடக்கு";i['doubleCheckDescription']="ஒரே காலத்தில் இரு துண்டுகளைக் கொண்டு அடக்குதல், ஒரு வெளிபடுத்திய தாக்குதலின் விளைவாக நகரும் துண்டு மற்றும் திரை மறை நின்ற துண்டு இரண்டும் எதிராளியின் அரசரைத் தாக்கும்.";i['dovetailMate']="புறா வால் முற்றுகை";i['dovetailMateDescription']="அண்டை அரசரின் இரண்டு தப்பிக்கும் சதுக்கங்கள் நட்பு துண்டுகளால் தடுக்கப்பட்டிருக்க, அரசி முற்றுகையிடுகிறாள்.";i['endgame']="கடையாட்டம்";i['endgameDescription']="ஆட்டத்தின் இறுதிக் கட்டத்திலான சூழ்ச்சி.";i['enPassantAdjacentCaptureDescription']="A tactic involving the en passant rule, where a pawn can capture an opposing pawn that has just moved next to it with its initial two-square move.";i['epauletteMate']="Epaulette mate";i['epauletteMateDescription']="Two adjacent escape squares for a checked king are occupied by other pieces.";i['equality']="சமத்துவம்";i['equalityDescription']="தோல்வியடைந்த நிலையிலிருந்து திரும்பி வந்து, இழுபறி அல்லது சமநிலை நிலையைப் பெறுங்கள். (சமநிலை ≤ 200cp)";i['exposedKing']="அம்பலமான அரசர்";i['exposedKingDescription']="ஒரு அரசரைச் சுற்றி சில பாதுகாவலர்கள் இருப்பது போன்ற ஒரு சூழ்ச்சி, இது பெரும்பாலும் முற்றுகைக்கு வழிவகுக்கிறது.";i['fork']="கவர்";i['forkOpposingPiecesDescription']="A move where a piece attacks two or more opposing pieces simultaneously.";i['hangingPiece']="வாட்டமான துண்டு";i['hangingPieceDescription']="எதிராளியின் துண்டைப் பாதுகாக்காமல் அல்லது போதுமான அளவு பாதுகாக்காமல், கைப்பற்ற சுதந்திரமாக இருப்பதை உள்ளடக்கிய ஒரு சூழ்ச்சி.";i['hookMate']="தூண்டில் முற்றுகை";i['hookMateOpposingPawnDescription']="Checkmate using a rook, knight, and pawn, where an opposing pawn blocks the king's escape.";i['interference']="குறுக்கீடு";i['interferenceDescription']="எதிராளியின் இரண்டு துண்டுகளுக்கு இடையில் ஒரு துண்டை நகர்த்தி, ஒன்று அல்லது இரண்டு துண்டுகளையும் பாதுகாக்காமல் விட்டுவிடுதல், உதாரணமாக, இரண்டு யானைகளுக்கு இடையில் பாதுகாக்கப்பட்ட சதுக்கத்தில் ஒரு குதிரையைப் போல.";i['intermezzo']="இடையிசை";i['intermezzoDescription']="எதிர்பார்த்த நகர்வை இயக்குவதற்குப் பதிலாக, எதிராளி பதிலளிக்க வேண்டிய உடனடி அச்சுறுத்தலை ஏற்படுத்தும் மற்றொரு நகர்வை முதலில் இடைமறிக்கவும். இது \"சுவிசென்சுக்\" அல்லது \"இடைவெளியில்\" என்றும் அழைக்கப்படுகிறது.";i['killBoxMate']="கொலைப் பெட்டி முற்றுகை";i['killBoxMateDescription']="எதிரி அரசருக்கு அடுத்ததாக ஒரு யானை உள்ளது மற்றும் ஒரு அரசியால் ஆதரிக்கப்படுகிறது, அது அரசர் தப்பிக்கும் சதுக்கங்களையும் தடுக்கிறது. யானை மற்றும் அரசி எதிரி அரசரை 3 க்கு 3 \"கொலைப் பெட்டி\"யில் பிடிக்கிறார்கள்.";i['kingsideAttack']="அரசர் பக்க தாக்குதல்";i['kingsideAttackDescription']="எதிராளி அரசர் பக்கம் கோட்டை அமைத்தபிறகு, அரசரைத் தாக்குதல்.";i['knightEndgame']="குதிரை கடையாட்டம்";i['knightEndgameDescription']="குதிரைகளும் பணயங்களும் மட்டுமே கொண்ட ஒரு கடையாட்டம்.";i['long']="நீண்ட புதிர்";i['longDescription']="வெற்றி பெற மூன்று நகர்வுகள்.";i['master']="வல்லுநர் ஆட்டங்கள்";i['masterDescription']="தலைப்பு ஆட்டக்காரர்கள் விளையாடும் விளையாட்டுகளிலிருந்து புதிர்கள்.";i['masterVsMaster']="வல்லுநர் vs வல்லுநர் விளையாட்டுகள்";i['masterVsMasterDescription']="இரண்டு தலைப்பு ஆட்டக்காரர்களுக்கு இடையிலான விளையாட்டுகளிலிருந்து புதிர்கள்.";i['mate']="முற்றுகை";i['mateDescription']="ஒயிலுடன் விளையாட்டை வெல்லுங்கள்.";i['mateIn1']="1 இல் முற்றுகை";i['mateIn1Description']="ஒரே நகர்வில் முற்றுகையிடுங்கள்.";i['mateIn2']="2 இல் முற்றுகை";i['mateIn2Description']="இரு நகர்வுகளில் முற்றுகையிடுங்கள்.";i['mateIn3']="3 இல் முற்றுகை";i['mateIn3Description']="மூன்று நகர்வுகளில் முற்றுகையிடுங்கள்.";i['mateIn4']="4 இல் முற்றுகை";i['mateIn4Description']="நான்கு நகர்வுகளில் முற்றுகையிடுங்கள்.";i['mateIn5']="5 அல்லது அதற்கு மேற்பட்டவற்றில் முற்றுகை";i['mateIn5Description']="நீண்ட முற்றுகை தொடர்வரிசையைக் கண்டறியவும்.";i['middlegame']="இடையாட்டம்";i['middlegameDescription']="ஆட்டத்தின் இரண்டாம் கட்டத்தின்போது ஒரு சூழ்ச்சி.";i['mix']="நலமான கலவை";i['mixDescription']="எல்லாவற்றிலும் துணுக்கு. என்ன எதிர்பார்க்க வேண்டும் என்று உங்களுக்குத் தெரியாது, எனவே நீங்கள் எதற்கும் தயாராக இருக்கிறீர்கள்! உண்மையான விளையாட்டுகளைப் போலவே.";i['morphyMateBishopAndRookDescription']="A bishop delivers checkmate to the king, while a rook helps confine it.";i['morphysMate']="Morphy's mate";i['oneMove']="ஒரு-நகர்வு புதிர்";i['oneMoveDescription']="ஒரே ஒரு நகர்வு நீளமுள்ள ஒரு புதிர்.";i['opening']="துவக்கம்";i['openingDescription']="ஆட்டத்தின் முதல் கட்டத்தின்போது ஒரு சூழ்ச்சி.";i['operaMate']="Opera mate";i['operaMateDescription']="Check the king with a rook and use a bishop to defend the rook.";i['pawnEndgame']="பணய கடையாட்டம்";i['pawnEndgameDescription']="பணயங்கள் மட்டுமே கொண்ட ஒரு கடையாட்டம்.";i['pillsburyMateRookAndBishopDescription']="A rook delivers checkmate to the king, while a bishop helps confine it.";i['pillsburysMate']="Pillsbury's mate";i['pin']="குண்டூசி";i['pinDescription']="அதிக மதிப்புள்ள துண்டின் மீதான தாக்குதலை வெளிப்படுத்தாமல் ஒரு துண்டு நகர முடியாத நிலையில், குண்டூசிகளை உள்ளடக்கிய ஒரு சூழ்ச்சி.";i['playerGames']="ஆட்டக்காரர் விளையாட்டுகள்";i['playerGamesDescription']="உங்கள் விளையாட்டுகளிலிருந்து அல்லது வேறொரு ஆட்டக்காரரின் விளையாட்டுகளிலிருந்து உருவாக்கப்பட்ட புதிர்களைத் தேடுங்கள்.";i['promotePawnToQueenRookOrMinor']="Promote one of your pawns to a queen, rook or minor piece.";i['promotion']="உயர்வு";i['puzzleDownloadInformation']=s("இந்தப் புதிர்கள் பொது செயற்களதில் உள்ளன, மேலும் %s இலிருந்து பதிவிறக்கம் செய்யலாம்.");i['queenEndgame']="அரசி கடையாட்டம்";i['queenEndgameDescription']="அரசிகளும் பணயங்களும் மட்டுமே கொண்ட ஒரு கடையாட்டம்.";i['queenRookEndgame']="அரசி மற்றும் யானை";i['queenRookEndgameDescription']="அரசிகள், யானைகள் மற்றும் பணயங்கள் மட்டுமே கொண்ட ஒரு கடையாட்டம்.";i['queensideAttack']="அரசி பக்கத் தாக்குதல்";i['queensideAttackDescription']="அரசியின் பக்கத்தில் கோட்டை அமைத்தபிறகு, எதிராளியின் அரசரைத் தாக்குதல்.";i['quietMove']="அரவமற்ற நகர்வு";i['quietMoveDescription']="அடக்கவோ அல்லது கைப்பற்றலைச் செய்யாத, அல்லது கைப்பற்றுவதற்கான உடனடி அச்சுறுத்தலை ஏற்படுத்தாத ஒரு நடவடிக்கை, ஆனால் பின்னர் ஒரு நகர்வுக்கு மிகவும் மறைக்கப்பட்ட தவிர்க்க முடியாத அச்சுறுத்தலைத் தயாரிக்கிறது.";i['rookEndgame']="யானை கடையாட்டம்";i['rookEndgameDescription']="யானைகளும் பணயங்களும் மட்டுமே கொண்ட ஒரு கடையாட்டம்.";i['sacrifice']="பலி";i['sacrificeDescription']="தொடர்ச்சியான கட்டாய நகர்வுகளுக்குப் பிறகு மீண்டும் ஒரு ஆதாயத்தைப் பெற, குறுகிய காலத்திற்கு பொருட்களை விட்டுக்கொடுப்பதை உள்ளடக்கிய ஒரு சூழ்ச்சி.";i['short']="குறுகிய புதிர்";i['shortDescription']="வெற்றி பெற இரண்டு நகர்வுகள்.";i['skewer']="சூலம்";i['skewerDescription']="அதிக மதிப்புள்ள ஒரு துண்டு தாக்கப்பட்டு, அதை வழியிலிருந்து நகர்த்தி, அதன் பின்னால் உள்ள குறைந்த மதிப்புள்ள ஒரு துண்டு பிடிக்கப்படவோ அல்லது தாக்கப்படவோ அனுமதிக்கும் ஒரு மையக்கரு, இது ஒரு குண்டூசியின் தலைகீழ்.";i['smotheredMate']="திணறடிக்கப்பட்ட முற்றுகை";i['smotheredMateDescription']="குதிரையால் வழங்கப்படும் ஒரு முற்றுகை, அதில் முற்றுகை செய்யப்பட்ட அரசர் அதன் சொந்த துண்டுகளால் சூழப்பட்டிருப்பதால் (அல்லது அடக்கப்பட்டிருப்பதால்) நகர முடியாது.";i['superGM']="மீத்திறன் GM விளையாட்டுகள்";i['superGMDescription']="உலகின் சிறந்த ஆட்டக்காரர்கள் விளையாடும் விளையாட்டுகளிலிருந்து புதிர்கள்.";i['swallowstailMate']="Swallow's tail mate";i['swallowstailMateDescription']="A checkmate pattern that visually resembles the appearance of a swallow’s tail, similar to a V shape.";i['trappedPiece']="அகப்பட்ட துண்டு";i['trappedPieceDescription']="ஒரு துண்டிற்கு நகர்வுகள் குறைவாக இருப்பதால், அது பிடிபடுவதிலிருந்து தப்பிக்க முடியாது.";i['triangleMate']="Triangle mate";i['triangleMateDescription']="The queen and rook, one square away from the enemy king, are on the same rank or file, separated by one square, forming a triangle.";i['underPromotion']="குறைவான உயர்வு";i['underPromotionDescription']="குதிரை, நெடுங்கோணி அல்லது யானையாக உயர்வு.";i['veryLong']="மிக நீண்ட புதிர்";i['veryLongDescription']="வெற்றி பெற நான்கு அல்லது அதற்கு மேற்பட்ட நகர்வுகள்.";i['vukovicMate']="உகோவிக் முற்றுகை";i['vukovicMateDescription']="ஒரு யானை மற்றும் குதிரையும் இணைந்து அரசரை முற்றுகையிடுதல். அரசரின் தப்பிக்கும் சதுக்கங்களை குதிரை தடுக்க, மூன்றாம் துண்டு ஆதரிக்க யானை முற்றுகை செய்கிறது.";i['xRayAttack']="ஊடு கதிர் தாக்குதல்";i['xRayAttackDescription']="ஒரு துண்டு எதிரியின் ஒரு துண்டு வழியாக ஒரு சதுக்கத்தைத் தாக்குகிறது அல்லது பாதுகாக்கிறது.";i['zugzwang']="வலுக்கட்டாயம்";i['zugzwangDescription']="எதிராளியால் செய்யக்கூடிய நகர்வுகள் குறைவாகவே இருக்கும், மேலும் அனைத்து நகர்வுகளும் அவர்களின் நிலையை மோசமாக்கும்.";i['enPassantDescription']="தனது துவக்க இரண்டு சதுக்க நகர்வைப் பயன்படுத்தி, தன்னைத் தவிர்த்துச் சென்ற எதிராளி பணயத்தைப் பிடிக்கக்கூடிய வழி மடக்கு விதியை உள்ளடக்கிய ஒரு சூழ்ச்சி.";i['forkDescription']="நகர்த்தப்பட்ட காய் ஒரே நேரத்தில் இரண்டு எதிராளி காய்களைத் தாக்கும் ஒரு நகர்வு.";i['hookMateDescription']="எதிரி அரசரின் தப்பிப்பைக் கட்டுப்படுத்த ஒரு யானை, குதிரை, மற்றும் ஒரு எதிரி பணயத்துடன் பணயம் ஆகியவற்றைக் கொண்டு முற்றுகையிடுங்கள்.";i['promotionDescription']="உங்கள் பணயம் ஒன்றை அரசி அல்லது சிறிய துண்டாக உயர்த்தவும்."})()